#!/usr/bin/env bash
# Catch a PR branch that carries local-master sediment instead of a clean cut
# from the product remote's master.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later
#
# The product base is the master of the remote whose URL is EasyIME/PIME,
# found by URL rather than remote name: checkouts disagree on whether that
# remote is called `origin` or `upstream`, and comparing against the fork's
# master is worthless because the fork's master is the integration branch
# and carries docs/agents, tests and CI wiring by design.
# A branch cut from the integration branch always drags in files upstream
# never carries: docs/agents, GLOSSARY.md.  The Windows box and the omp
# checkout have no local master, and a fork mirror can sit at the same SHA
# as master, blinding the merge-base test; the tracked-path check below
# catches those layouts where the ancestry test cannot.
#
# A branch cut from the integration branch contains those local commits, so
# the product master stops being an ancestor of it; and any branch whose diff
# touches harness paths leaks them into a product PR. Both are FAILs here.
#
# Usage: check_pr_scope.sh [<branch>|<sha>]   (default: current branch)
#        Stand in the PR worktree when you run it: the tracked-path check
#        reads the index of the checkout you are standing in, so running it
#        from the integration checkout FAILs even a clean branch
#        (docs/agents/upstream-pr.md).
# Exit codes: 0 clean, 1 dirty, 125 not applicable (integration branch, pull
# request based on an integration branch, detached HEAD without an argument,
# or no EasyIME/PIME remote).
# tests/check_pr_scope_test.sh pins these exit codes; rerun it after edits.

set -u

ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  PR scope (not inside a git checkout)\n'
    exit 125
}
cd "$ROOT"

target=${1:-}
if [ -z "$target" ]; then
    target=${GITHUB_HEAD_REF:-}
fi
if [ -z "$target" ]; then
    target=$(git symbolic-ref --short -q HEAD 2>/dev/null || true)
    [ -n "$target" ] || { printf 'SKIP  PR scope (detached HEAD, pass a branch)\n'; exit 125; }
fi

case "$target" in
    master|main|local/linux-master|omp/master|win/*)
        printf 'SKIP  PR scope (%s is an integration branch)\n' "$target"
        exit 125
        ;;
esac

# A pull_request run whose base is an integration branch tests harness work,
# which carries docs/agents and tests by design; only product-bound branches
# must be clean. master stays out of this list: a pull request into the fork's
# master (a mirror of the product master) still has to pass every check.
case "${GITHUB_BASE_REF:-}" in
    local/linux-master|omp/master|win/*)
        printf 'SKIP  PR scope (base %s is an integration branch)\n' "$GITHUB_BASE_REF"
        exit 125
        ;;
esac

# Tracked-path check: integration-only files must never ride a PR branch,
# whatever remote layout this checkout uses.
leaked=$(git ls-files -- docs/agents GLOSSARY.md .scratch | head -n 3)
if [ -n "$leaked" ]; then
    printf 'FAIL  PR scope (HEAD tracks integration-only files upstream lacks):\n'
    printf '%s\n' "$leaked" | sed 's/^/  /'
    exit 1
fi

base_ref=
for remote in $(git remote); do
    case "$(git config --get "remote.$remote.url" || true)" in
        *EasyIME/PIME*) base_ref="$remote/master"; break ;;
    esac
done
if [ -z "$base_ref" ]; then
    printf 'SKIP  PR scope (no EasyIME/PIME remote; add it and fetch first)\n'
    exit 125
fi
git rev-parse --verify --quiet "$base_ref" >/dev/null || {
    printf 'SKIP  PR scope (%s absent; git fetch %s first)\n' "$base_ref" "${base_ref%/*}"
    exit 125
}

if ! git merge-base --is-ancestor "$base_ref" "$target" 2>/dev/null; then
    printf 'FAIL  PR scope: %s does not sit on %s\n' "$target" "$base_ref"
    printf 'commits the PR would carry beyond %s:\n' "$base_ref"
    git log --oneline "$base_ref..$target" | head -20
    printf 'Cut the branch from %s and cherry-pick the product commits,\n' "$base_ref"
    printf 'or: git rebase --onto %s <base>\n' "$base_ref"
    exit 1
fi

leaked=$(git diff --name-only "$base_ref...$target" 2>/dev/null \
    | grep -E '^tests/|^docs/|^GLOSSARY\.md|^AGENTS\.md|^CLAUDE\.md' || true)
if [ -n "$leaked" ] && [ "${CHECK_PR_SCOPE_ALLOW:-0}" != 1 ]; then
    printf 'FAIL  PR scope: %s carries harness files into a product PR:\n' "$target"
    printf '%s\n' "$leaked"
    printf 'Leave them on the integration branch, or CHECK_PR_SCOPE_ALLOW=1 when the maintainer asked for them.\n'
    exit 1
fi

printf 'PASS  PR scope (%s is on %s, %s file(s) beyond it)\n' \
    "$target" "$base_ref" "$(git diff --name-only "$base_ref...$target" | wc -l)"
